import 'package:flutter_test/flutter_test.dart';

import 'package:rcpu_wallet/core/crypto/native_tx.dart';

/// TC-NTX-V3-01：v3（CT）交易编解码对照链上真实已确认交易回归。
///
/// 样本取自高度 14690（txid 1c41a87ddc4d399939e1040dae67cb4522cff4488c569088
/// ab14fc81efbbb21c），经节点 `decoderawtransaction` 逐项核对：
/// - segwit marker/flag 标准 BIP144（`0001` 紧随 version）；
/// - 每个输入 sequence 后带 1 字节 0x00 尾字段；
/// - 输出布局 value || nonce || rangeproof || scriptPubKey
///   （rangeproof 在脚本**之前**，本链自定义 CTxOut 布局）；
/// - 显式金额为 8 字节**大端**：vout[5] = 7,602,000 micro = 0.07602 RCPU
///   （手续费输出，空脚本），与节点解码完全一致；
/// - witness 位于 vout 与 locktime 之间（每输入 [71B ECDSA sig, 33B 压缩公钥]）。
///
/// 该样本曾导致线上 bug：旧编解码按 v2 布局解析 v3 交易，抛
/// `FormatException: 交易尾部存在多余字节`（CT 转账在锚定校验处失败）。
const onchainV3Hex =
    '';

void main() {
  test('v3 链上已确认交易：解析字段与节点 decoderawtransaction 一致', () {
    final tx = NativeTxCodec.parseHex(onchainV3Hex);

    expect(tx.version, 3);
    expect(tx.inputs.length, 2);
    expect(tx.outputs.length, 6);
    expect(tx.locktime, 0);

    // 输入：空 scriptSig + sequence=0xffffffff（v3 尾字段 0x00 已被解析吸收）。
    for (final i in tx.inputs) {
      expect(i.scriptSig.length, 0);
      expect(i.sequence, 0xffffffff);
    }

    // 4 个显式 P2WPKH 输出（8B 大端金额，空 nonce，空 rangeproof）。
    final plain = [210000000000, 210000000000, 70000000000, 10000000000];
    final spks = [
      '00146c0032616b9e2ad1abd048941fbcdcb1025c56e3',
      '001417b7eba80e34bc9135bcc47131f2ae7876ca4f1e',
      '00142233b7b23fea77ae4b3949bc0476792207ac362c',
      '0014f5c52b93d0cf4dc6699b3ca516f5ca373e8ae988',
    ];
    for (var k = 0; k < 4; k++) {
      final o = tx.outputs[k];
      expect(o.isConfidential, false);
      expect(o.value, BigInt.from(plain[k]));
      expect(NativeTxCodec.bytesToHex(o.scriptPubKey), spks[k]);
      expect(o.rangeproof, isNull);
      expect(o.nonceCommitment, isNull);
    }

    // 1 个盲化输出：09 金额承诺 + 04 Path C nonce 承诺 + 3141B rangeproof。
    final ct = tx.outputs[4];
    expect(ct.isConfidential, true);
    expect(ct.valueCommitment!.length, 33);
    expect(ct.valueCommitment![0], 0x09);
    expect(ct.nonceCommitment!.length, 33);
    expect(ct.nonceCommitment![0], 0x04);
    expect(ct.rangeproof!.length, 3141);
    expect(NativeTxCodec.bytesToHex(ct.scriptPubKey),
        '0014d040eb29949610426a001e933959e74c9816ab4a');

    // 显式手续费输出：大端 7,602,000 micro（0.07602 RCPU），空脚本。
    final fee = tx.outputs[5];
    expect(fee.isConfidential, false);
    expect(fee.value, BigInt.from(7602000));
    expect(fee.scriptPubKey.length, 0);

    // witness：每输入 [71B ECDSA 签名, 33B 压缩公钥]。
    for (final i in tx.inputs) {
      expect(i.witness.length, 2);
      expect(i.witness[0].length, 71);
      expect(i.witness[1].length, 33);
    }
  });

  test('v3 链上交易：解析后再序列化逐字节一致（round-trip）', () {
    final tx = NativeTxCodec.parseHex(onchainV3Hex);
    expect(NativeTxCodec.bytesToHex(tx.serialize()), onchainV3Hex);
  });

  test('v3 输入尾字节非 0x00 时 fail-closed', () {
    // version=3，1 输入（尾字段 0x01 非法）。
    const bad = '03000000'
        '01' '11' '11111111111111111111111111111111111111111111111111111111111111'
        '00000000' '00' 'ffffffff'
        '01' // 非法尾字段
        '00' // 0 输出
        '00000000';
    expect(() => NativeTxCodec.parseHex(bad), throwsFormatException);
  });
}
